class TO(Exception): pass
def h(*a): raise TO()
signal.signal(signal.SIGALRM, h)

def oracle(graph, rootimps):
    best = {}
    frontier = []
    for r in rootimps:
        if r not in best: best[r] = 1; frontier.append(r)
    while frontier:
        nxt = []
        for n in frontier:
            for m in graph[n]:
                if m not in best:
                    best[m] = best[n] + 1; nxt.append(m)
        frontier = nxt
    return {n for n, d in best.items() if d <= 4}, best

def build(base, graph, rootimps, rng):
    if base.exists(): shutil.rmtree(base)
    proj = base / "proj"; home = base / "home"
    proj.mkdir(parents=True); home.mkdir()
    ri = list(rootimps); rng.shuffle(ri)
