tmp = Path(tempfile.mkdtemp(dir="/private/tmp/claude-501/scratch")).resolve()
trials = mism = 0; notevar = {"depth": 0, "circ": 0}; order_bad = dup = hang = 0
repro_circ = None; repro_mis = None; graphs = 0
for g in range(400):
