    # bias to chains sometimes
    if rng.random() < .4:
        for i in range(n-1):
            if rng.random() < .8 and names[i+1] not in graph[names[i]]: graph[names[i]].append(names[i+1])
    rootimps = rng.sample(names, rng.randint(1, 5))
    exp, best = oracle(graph, rootimps)
    graphs += 1
    dn, cn = [], []
    for t in range(8):
        proj, home = build(tmp / "t", graph, rootimps, rng)
        signal.alarm(5)
        try:
            files = discover(proj, home)
        except TO:
            hang += 1; continue
        finally:
            signal.alarm(0)
        trials += 1
        imps = [f for f in files if f.scope == Scope.IMPORT and f.path.is_relative_to(tmp)]
        got = {f.path.stem for f in imps}
        if len(imps) != len(got): dup += 1
        mine = [f for f in files if f.path.is_relative_to(tmp)]
        if [f.order for f in mine] != list(range(mine[0].order, mine[0].order + len(mine))): order_bad += 1
        if got != exp:
            mism += 1
            if repro_mis is None: repro_mis = (graph, rootimps, got ^ exp)
        dn.append(frozenset((f.path.stem, x) for f in mine for x in f.notes if x.startswith("import depth")))
        cn.append(frozenset((f.path.stem, x) for f in mine for x in f.notes if x.startswith("circular")))
        # depth note oracle: file with final hop 4 and an import (non-chain?) -> note expected
    if len(set(dn)) > 1: notevar["depth"] += 1
    if len(set(cn)) > 1:
        notevar["circ"] += 1
        if repro_circ is None: repro_circ = (graph, rootimps, set(cn))
print("graphs", graphs, "trials", trials, "mismatch", mism, "dups", dup, "order_bad", order_bad, "hang", hang)
print("graphs with varying depth notes", notevar["depth"], "circ notes", notevar["circ"])
print("mis repro", repro_mis)
print("circ repro", repro_circ)
shutil.rmtree(tmp)
